-- Disposable format/projection fixture, not production Kafka configuration.
CREATE TABLE points (
__PROJECTION_COLUMNS__
) ENGINE = ReplacingMergeTree
PARTITION BY event_day
ORDER BY (project_id, source_id, resource_id, metric_name, time_unix_nano, sample_id);

CREATE TABLE fixture_input AS points ENGINE = Null;
CREATE MATERIALIZED VIEW fixture_projection TO points AS SELECT * FROM fixture_input;
SYSTEM STOP MERGES points;
INSERT INTO fixture_input FROM INFILE '/contract/points.pb' SETTINGS format_schema='/schemas/recount.proto:AnalyticalPoint', format_protobuf_use_autogenerated_schema=0 FORMAT Protobuf;
INSERT INTO fixture_input FROM INFILE '/contract/points.pb' SETTINGS format_schema='/schemas/recount.proto:AnalyticalPoint', format_protobuf_use_autogenerated_schema=0 FORMAT Protobuf;

SELECT throwIf(count() != 30, 'ordinary rows still contain retries') FROM points;
SELECT throwIf(count() != 15, 'full original sample identity must retain distinct points') FROM points FINAL;
SELECT throwIf(min(int_value) != toInt64('-9223372036854775808') OR max(int_value) != toInt64('9223372036854775807'), 'Int64 precision') FROM points FINAL WHERE metric_name = 'integer.extremes';
SELECT throwIf(max(time_unix_nano) != toUInt64('18446744073709551615'), 'UInt64 nanoseconds') FROM points FINAL;
SELECT throwIf(count() != 1, 'missing scalar must not become zero') FROM points FINAL WHERE flags = 1 AND int_value IS NULL AND double_value IS NULL;
SELECT throwIf(count() != 1, 'histogram optionality and buckets') FROM points FINAL WHERE metric_name = 'distribution' AND count = 3 AND sum IS NULL AND min IS NULL AND max = 9 AND explicit_bounds = [0.5] AND bucket_counts = [toUInt64(1),toUInt64(2)];
SELECT throwIf(count() != 1, 'full UInt64 histogram count') FROM points FINAL WHERE metric_name = 'distribution' AND count = toUInt64('18446744073709551615') AND bucket_counts = [];
SELECT throwIf(count() != 1, 'exponential histogram structure') FROM points FINAL WHERE metric_name = 'exponential' AND scale = -7 AND zero_count = 1 AND zero_threshold = 0.001 AND positive_offset = -2 AND positive_counts = [toUInt64(2)] AND negative_offset = 4 AND negative_counts = [toUInt64(3)];
SELECT throwIf(count() != 1, 'present empty versus absent buckets') FROM points FINAL WHERE metric_name = 'exponential' AND positive_offset = 0 AND positive_counts = [] AND negative_offset IS NULL AND negative_counts = [] AND sum IS NULL;
SELECT throwIf(count() != 1, 'summary structure') FROM points FINAL WHERE metric_name = 'summary' AND count = 2 AND sum = -1 AND quantiles = [0.,1.] AND quantile_values = [-2.,1.];
SELECT throwIf(count() != 1, 'Int64 attributes remain typed') FROM points FINAL WHERE metric_name = 'arbitrary.authorized.metric' AND flags = 0 AND arrayExists(a -> a.1 = '/exact' AND a.2 = 3 AND a.4 = toInt64('9223372036854775807'), point_attributes);
SELECT throwIf(count() != 1, 'nested attributes remain queryable') FROM points FINAL WHERE metric_name = 'arbitrary.authorized.metric' AND flags = 0 AND arrayExists(a -> a.1 = '/nested~1a~0b/min' AND a.4 = toInt64('-9223372036854775808'), point_attributes);
SELECT throwIf(count() != 1, 'native GPU timestamp') FROM points FINAL WHERE resource_id = 'gpu-a' AND time_unix_nano = toUInt64('1780000000000000123');
SELECT throwIf(count() != 2, 'gateway sensor resources do not need host or topology') FROM points FINAL WHERE project_id = 'project-a' AND source_id = 'source-a' AND resource_kind = 8 AND host_id IS NULL;
SELECT throwIf(count() != 2, 'counter continuity segments') FROM (SELECT DISTINCT stream_id, continuity FROM points FINAL WHERE metric_name = 'counter');

-- Representative authorized selector: the application must supply project_id
-- only after independent access checks, never from an unchecked payload.
SELECT throwIf(count() != 1, 'project/resource/metric/time filter') FROM points FINAL
WHERE project_id = 'project-a' AND resource_id = 'sensor-a' AND metric_name = 'sensor.temperature'
  AND time_unix_nano >= toUInt64('1780000000000000300') AND time_unix_nano < toUInt64('1780000000000000301');
SELECT throwIf(count() != 0, 'cross-project filter') FROM points FINAL WHERE project_id = 'other-project';

-- Duplicate-sensitive calculations need an explicit logical uniqueness step.
-- Replacing background cleanup is not a correctness boundary.
SELECT throwIf(sum(double_value) != -25., 'fixture must expose duplicate-sensitive sum') FROM points WHERE metric_name = 'arbitrary.authorized.metric' AND flags = 0;
SELECT throwIf(sum(double_value) != -12.5, 'logical uniqueness before calculation') FROM points FINAL WHERE metric_name = 'arbitrary.authorized.metric' AND flags = 0;
SELECT throwIf(count() != 0, 'partition must be event-derived') FROM points FINAL WHERE event_day != intDiv(time_unix_nano,toUInt64('86400000000000'));
SELECT throwIf(count()!=1,'nullable present zero integer') FROM points FINAL WHERE resource_id='gpu-a' AND arrayExists(a->a.path='/zero-int' AND a.int_value=0 AND a.double_value IS NULL,resource_attributes);
SELECT throwIf(count()!=1,'nullable present zero double') FROM points FINAL WHERE resource_id='gpu-a' AND arrayExists(a->a.path='/zero-double' AND a.double_value=0 AND a.int_value IS NULL,resource_attributes);
SELECT throwIf(count()!=1,'nullable present false') FROM points FINAL WHERE resource_id='gpu-a' AND arrayExists(a->a.path='/false' AND a.bool_value=0 AND a.string_value IS NULL,resource_attributes);
SELECT throwIf(count()!=1,'nullable present empty bytes and string') FROM points FINAL WHERE resource_id='gpu-a' AND arrayExists(a->a.path='/empty-string' AND a.string_value='',resource_attributes) AND arrayExists(a->a.path='/empty-bytes' AND a.bytes_value='',resource_attributes);
SELECT throwIf(count()!=1,'native binary attribute') FROM points FINAL WHERE metric_name='arbitrary.authorized.metric' AND flags=0 AND arrayExists(a->a.path='/bytes' AND hex(a.bytes_value)='00FF',point_attributes);
SELECT * FROM points FINAL ORDER BY sample_id INTO OUTFILE '/result/roundtrip.pb' FORMAT Protobuf SETTINGS format_schema='/schemas/recount.proto:AnalyticalPoint', format_protobuf_use_autogenerated_schema=0;
SELECT 'contract SQL assertions passed';
